    @Override
    public void drawOnly(List<ModelPart> keep) {
        for (int i = 0, n = allParts.size(); i < n; i++)
            allParts.get(i).skipDraw = true;
        for (int i = 0, n = keep.size(); i < n; i++)
            keep.get(i).skipDraw = false;
    }

    @Override
    public void drawAll() {
        for (int i = 0, n = allParts.size(); i < n; i++)
            allParts.get(i).skipDraw = false;
    }

